mapper.select:
SELECT ROOM_ID
  FROM CONSULT_ROOM
 WHERE MEMBER_ID = #{memberId}

SELECT MEMBER_ID
  FROM CONSULT_ROOM
 WHERE ROOM_ID = #{roomId}

SELECT FROM CONSULT_MESSAGE c JOIN MEMBER m ON m.MEMBER_ID = c.SENDER_ID WHERE c.ROOM_ID = #{roomId}
AND c.MESSAGE_ID < #{beforeId}
ORDER BY c.MESSAGE_ID DESC FETCH FIRST #{limit} ROWS ONLY
